package ktanesolver.module.modded.regular.the_crystal_maze;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class TheCrystalMazeSolverTest{private final TheCrystalMazeSolver solver=new TheCrystalMazeSolver();
	@Test void solvesIndustrialAndUnlocksDomeAfterRecordingCrystal(){ModuleEntity module=new ModuleEntity();SolveSuccess<TheCrystalMazeOutput>industrial=solve(module,input(TheCrystalMazeInput.World.INDUSTRIAL,"ABCDE",null,null));assertThat(industrial.solved()).isFalse();assertThat(industrial.output().answer()).isZero();assertThat(industrial.output().actions()).containsExactly("Set the display to 0","Press REVERSE");assertThat(module.getState().get("crystalMazeWorlds")).isEqualTo(List.of("INDUSTRIAL"));SolveSuccess<TheCrystalMazeOutput>dome=solve(module,input(TheCrystalMazeInput.World.DOME,null,null,null));assertThat(dome.solved()).isTrue();assertThat(dome.output().crystals()).isEqualTo(1);}
	@Test void findsEveryFuturisticAnomaly(){TheCrystalMazeOutput out=solve(new ModuleEntity(),input(TheCrystalMazeInput.World.FUTURISTIC,null,List.of("RED/RED BLUE/BLUE GREEN/YELLOW","RED/RED BLUE/GREEN YELLOW/PURPLE","PURPLE/BLUE GREEN/GREEN YELLOW/YELLOW"),null)).output();assertThat(out.targets()).containsExactly("SCREEN 1: GREEN/YELLOW","SCREEN 2: RED/RED","SCREEN 3: PURPLE/BLUE");}
	@Test void calculatesMedievalPrimeSum(){TheCrystalMazeOutput out=solve(new ModuleEntity(),input(TheCrystalMazeInput.World.MEDIEVAL,null,null,List.of("BLUE/CW","BROWN/CCW","GREEN/CW","PURPLE/CCW"))).output();assertThat(out.answer()).isEqualTo(7);}
	@Test void aztecPlanReplaysToExactWeightAcrossSwitches(){List<String>path=TheCrystalMazeSolver.aztecPath(125,15,15,15,2);assertThat(path).isNotNull();int weight=15,clicks=15,left=2;for(String action:path){weight+=action.equals("LEFT")?left:3-left;clicks++;if(clicks%15==0)left=3-left;}assertThat(weight).isEqualTo(125);}
	@Test void rejectsDomeWithoutCrystalAndMalformedWorldData(){assertThat(solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),input(TheCrystalMazeInput.World.DOME,null,null,null))).isInstanceOf(SolveFailure.class);assertThat(solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),input(TheCrystalMazeInput.World.FUTURISTIC,null,List.of("RED/RED RED/RED RED/RED","",""),null))).isInstanceOf(SolveFailure.class);}
	private static TheCrystalMazeInput input(TheCrystalMazeInput.World world,String serial,List<String>screens,List<String>rings){return new TheCrystalMazeInput(world,125,15,15,15,List.of(2,1),serial,screens,rings);}@SuppressWarnings("unchecked")private SolveSuccess<TheCrystalMazeOutput>solve(ModuleEntity module,TheCrystalMazeInput input){return(SolveSuccess<TheCrystalMazeOutput>)solver.solve(new RoundEntity(),new BombEntity(),module,input);}}
